def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D'

    opp_actions = [h[1] for h in history]
    opp_def_count = opp_actions.count('D')

    if n == 99:
        return 'D'

    if opp_def_count == 0:
        if n >= 95:
            return 'D'
        if n >= 6 and n % 6 == 0:
            return 'D'
        return 'C'

    if n >= 2:
        if opp_actions[-1] == 'D' and opp_actions[-2] == 'D':
            return 'D'
        return 'C'
    return 'C'
